import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import stallService from '../services/stallService';
import StallCard from '../components/StallCard';
import { isValidText, isValidPositiveNumber } from '../utils/helpers';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const StallAllocation = () => {
  const { eventId } = useParams();
  const [stalls, setStalls] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [filterStatus, setFilterStatus] = useState(null); // null, 'approved', 'pending'
  const [requestData, setRequestData] = useState({
    stallName: '',
    category: '',
    size: '',
    price: '',
  });
  const [errors, setErrors] = useState({});

  useEffect(() => {
    fetchStalls();
  }, [eventId]);

  const fetchStalls = async () => {
    setLoading(true);
    try {
      const data = await stallService.getStallsByEvent(eventId);
      setStalls(data);
    } catch (error) {
      toast.error('Failed to fetch stalls');
    } finally {
      setLoading(false);
    }
  };

  const handleRequestStall = async (e) => {
    e.preventDefault();

    // Validate form
    const newErrors = validateStallForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      toast.error('Please fill in all required fields correctly');
      return;
    }

    try {
      await stallService.requestStall({
        ...requestData,
        event: eventId,
      });
      toast.success('Stall request submitted!');
      setShowRequestForm(false);
      setRequestData({ stallName: '', category: '', size: '', price: '' });
      setErrors({});
      fetchStalls();
    } catch (error) {
      toast.error('Failed to request stall');
    }
  };

  const validateStallForm = () => {
    const newErrors = {};

    // Stall name validation
    if (!requestData.stallName.trim()) {
      newErrors.stallName = 'Stall name is required';
    } else if (!isValidText(requestData.stallName, 3)) {
      newErrors.stallName = 'Stall name must be at least 3 characters';
    }

    // Category validation
    if (!requestData.category) {
      newErrors.category = 'Category is required';
    }

    // Size validation
    if (!requestData.size) {
      newErrors.size = 'Size is required';
    }

    // Price validation
    if (!requestData.price) {
      newErrors.price = 'Price is required';
    } else if (!isValidPositiveNumber(requestData.price)) {
      newErrors.price = 'Price must be a positive number';
    }

    return newErrors;
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setRequestData(prev => ({
      ...prev,
      [name]: value,
    }));
    // Clear field error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: '',
      }));
    }
  };

  return (
    <div className="stall-allocation-page">
      <div className="page-header">
        <h1>Stall Allocation</h1>
        <p>Request stalls for the event</p>
      </div>

      <div className="stall-content">
        {/* Filter Buttons */}
        <div className="filters">
          <button 
            className={`filter-btn ${filterStatus === 'approved' ? 'active' : ''}`}
            onClick={() => setFilterStatus('approved')}
          >
            ✅ Approved
          </button>
          <button 
            className={`filter-btn ${filterStatus === 'pending' ? 'active' : ''}`}
            onClick={() => setFilterStatus('pending')}
          >
            ⏳ Pending
          </button>
        </div>

        {/* Request Section */}
        <div className="request-section-top">
          <button 
            className="btn-primary"
            onClick={() => setShowRequestForm(!showRequestForm)}
          >
            {showRequestForm ? 'Cancel' : '+ Request New Stall'}
          </button>

          {showRequestForm && (
            <form className="stall-request-form" onSubmit={handleRequestStall}>
              <div className="form-group">
                <label htmlFor="stallName">Stall Name *</label>
                <input
                  type="text"
                  id="stallName"
                  name="stallName"
                  value={requestData.stallName}
                  onChange={handleInputChange}
                  required
                  placeholder="Enter stall name (minimum 3 characters)"
                  className={errors.stallName ? 'input-error' : ''}
                />
                {errors.stallName && <span className="error-text">{errors.stallName}</span>}
              </div>

              <div className="form-group">
                <label htmlFor="category">Category *</label>
                <select
                  id="category"
                  name="category"
                  value={requestData.category}
                  onChange={handleInputChange}
                  required
                  className={errors.category ? 'input-error' : ''}
                >
                  <option value="">Select category</option>
                  <option value="food">Food</option>
                  <option value="crafts">Crafts</option>
                  <option value="retail">Retail</option>
                  <option value="other">Other</option>
                </select>
                {errors.category && <span className="error-text">{errors.category}</span>}
              </div>

              <div className="form-group">
                <label htmlFor="size">Size *</label>
                <select
                  id="size"
                  name="size"
                  value={requestData.size}
                  onChange={handleInputChange}
                  required
                  className={errors.size ? 'input-error' : ''}
                >
                  <option value="">Select size</option>
                  <option value="small">Small (10x10)</option>
                  <option value="medium">Medium (15x15)</option>
                  <option value="large">Large (20x20)</option>
                </select>
                {errors.size && <span className="error-text">{errors.size}</span>}
              </div>

              <div className="form-group">
                <label htmlFor="price">Price (per day) *</label>
                <input
                  type="number"
                  id="price"
                  name="price"
                  value={requestData.price}
                  onChange={handleInputChange}
                  required
                  placeholder="Enter price"
                  min="0"
                  className={errors.price ? 'input-error' : ''}
                />
                {errors.price && <span className="error-text">{errors.price}</span>}
              </div>

              <button type="submit" className="btn-success">
                Submit Request
              </button>
            </form>
          )}
        </div>

        {loading ? (
          <div className="loading">Loading stalls...</div>
        ) : filterStatus === null ? (
          <div className="empty-state">
            <div className="empty-icon">📋</div>
            <h2>Select a Filter</h2>
            <p>Click a button above to view approved or pending stalls</p>
          </div>
        ) : (
          <>
            {filterStatus === 'approved' && (
              <div className="stall-section">
                <div className="section-header">
                  <h2>✅ Approved Stalls</h2>
                  <span className="stall-count">{stalls.filter(s => s.approvalStatus === 'approved').length}</span>
                </div>
                {stalls.filter(s => s.approvalStatus === 'approved').length > 0 ? (
                  <div className="stalls-grid">
                    {stalls.filter(s => s.approvalStatus === 'approved').map(stall => (
                      <StallCard
                        key={stall._id}
                        stall={stall}
                        onBook={() => {}}
                        onViewDetails={() => {}}
                      />
                    ))}
                  </div>
                ) : (
                  <p className="no-stalls">No approved stalls yet</p>
                )}
              </div>
            )}

            {filterStatus === 'pending' && (
              <div className="stall-section">
                <div className="section-header">
                  <h2>⏳ Pending Stalls</h2>
                  <span className="stall-count">{stalls.filter(s => s.approvalStatus === 'pending').length}</span>
                </div>
                {stalls.filter(s => s.approvalStatus === 'pending').length > 0 ? (
                  <div className="stalls-grid">
                    {stalls.filter(s => s.approvalStatus === 'pending').map(stall => (
                      <StallCard
                        key={stall._id}
                        stall={stall}
                        onBook={() => {}}
                        onViewDetails={() => {}}
                      />
                    ))}
                  </div>
                ) : (
                  <p className="no-stalls">No pending stalls</p>
                )}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default StallAllocation;
